}

NP_API BOOL SaveTab(HWND hPanel, int index, BOOL saveAs)
{
    NotepadInstance *inst = GetInstance(hPanel);
    if (!inst || index < 0 || index >= (int)inst->docs.size())
        return FALSE;
    SetActiveDoc(inst, index);
    DoSave(inst, saveAs != FALSE);
    return !inst->modified;
}

