Now rewrite the theme API section. I need a helper to apply the palette to documents (used by SetTheme and SetThemeMode). Let me create:

```cpp
/// Re-applies the current palette to every editor. Rich Edit needs its default
/// character format pushed again because EM_SETCHARFORMAT overrides the
/// control colours that SetWindowTheme supplies.
static void ApplyThemeToDocuments(NotepadInstance *inst)
{
    for (Document *doc : inst->docs)
    {
        if (!doc->hEdit)
            continue;
        SendMessageW(doc->hEdit, EM_SETBKGNDCOLOR, 0, inst->theme.BgApp);
        ApplyControlTheme(doc->hEdit, inst->darkMode);

        CHARFORMAT2W format = {};
        format.cbSize = sizeof(format);
        format.dwMask = CFM_COLOR;
        format.crTextColor = inst->theme.TextHi;
        SendMessageW(doc->hEdit, EM_SETCHARFORMAT, SCF_DEFAULT | SCF_ALL, (LPARAM)&format);
    }
    if (inst->hRenameEdit)
        ApplyControlTheme(inst->hRenameEdit, inst->darkMode);
    if (inst->hSearchFind)
        ApplyControlTheme(inst->hSearchFind, inst->darkMode);
    if (inst->hSearchRepl)
        ApplyControlTheme(inst->hSearchRepl, inst->darkMode);
}
```

And `static void ApplyThemeMode(NotepadInstance *inst, ThemeMode mode)` that sets themeMode, darkMode, palette (unless custom), repaints, and fires notify.

Then:
