// ---- Exported API: Theme ----

NP_API BOOL SetTheme(HWND hPanel, const NPTheme *theme)
{
    NotepadInstance *inst = GetInstance(hPanel);
    if (!inst)
        return FALSE;
    if (!theme)
    {
        inst->theme = DefaultDarkTheme();
    }
    else
    {
        inst->theme.BgApp = theme->bgApp;
        inst->theme.BgPanel = theme->bgPanel;
        inst->theme.BgCard = theme->bgCard;
        inst->theme.BgBtn = theme->bgBtn;
        inst->theme.BgBtnHi = theme->bgBtnHi;
        inst->theme.BgRailHi = theme->bgBtnHi;
        inst->theme.Border = theme->border;
        inst->theme.BorderSoft = theme->borderSoft;
        inst->theme.TextHi = theme->textHi;
        inst->theme.TextMid = theme->textMid;
        inst->theme.TextLow = theme->textLow;
        inst->theme.Accent = theme->accent;
        inst->theme.SelBg = theme->selBg;
        inst->theme.IconIdle = theme->iconIdle;
        inst->theme.IconActive = theme->iconActive;
        // Apply to RichEdit
        for (Document *d : inst->docs)
        {
            if (d->hEdit)
            {
                SendMessageW(d->hEdit, EM_SETBKGNDCOLOR, 0, inst->theme.BgApp);
                CHARFORMAT2W cf{};
                cf.cbSize = sizeof(cf);
                cf.dwMask = CFM_COLOR;
                cf.crTextColor = inst->theme.TextHi;
                SendMessageW(d->hEdit, EM_SETCHARFORMAT, SCF_DEFAULT | SCF_ALL, (LPARAM)&cf);
            }
        }
    }
    if (inst->hSelf)
        InvalidateRect(inst->hSelf, nullptr, TRUE);
    return TRUE;
}

NP_API BOOL GetTheme(HWND hPanel, NPTheme *outTheme)
{
    NotepadInstance *inst = GetInstance(hPanel);
    if (!inst || !outTheme)
        return FALSE;
    outTheme->bgApp = inst->theme.BgApp;
    outTheme->bgPanel = inst->theme.BgPanel;
    outTheme->bgCard = inst->theme.BgCard;
    outTheme->bgBtn = inst->theme.BgBtn;
    outTheme->bgBtnHi = inst->theme.BgBtnHi;
    outTheme->border = inst->theme.Border;
    outTheme->borderSoft = inst->theme.BorderSoft;
    outTheme->textHi = inst->theme.TextHi;
    outTheme->textMid = inst->theme.TextMid;
    outTheme->textLow = inst->theme.TextLow;
    outTheme->accent = inst->theme.Accent;
    outTheme->selBg = inst->theme.SelBg;
    outTheme->iconIdle = inst->theme.IconIdle;
    outTheme->iconActive = inst->theme.IconActive;
    return TRUE;
}

// ---- Exported API: Font ----

NP_API BOOL SetFontW(HWND hPanel, const LOGFONTW *logFont)
{
    NotepadInstance *inst = GetInstance(hPanel);
    if (!inst)
        return FALSE;
    if (!logFont)
    {
        ZeroMemory(&inst->logFont, sizeof(inst->logFont));
        wcscpy_s(inst->logFont.lfFaceName, L"Segoe UI");
        inst->logFont.lfHeight = -MulDiv(11, inst->dpi, 72);
        inst->logFont.lfWeight = FW_NORMAL;
        inst->logFont.lfCharSet = DEFAULT_CHARSET;
        inst->logFont.lfQuality = CLEARTYPE_QUALITY;
    }
    else
    {
        inst->logFont = *logFont;
    }
    ApplyEditorFont(inst);
    return TRUE;
}

NP_API BOOL GetFontW(HWND hPanel, LOGFONTW *outLogFont)
{
    NotepadInstance *inst = GetInstance(hPanel);
    if (!inst || !outLogFont)
        return FALSE;
    *outLogFont = inst->logFont;
    return TRUE;
}

