LRESULT CALLBACK MenuProc(HWND h, UINT m, WPARAM w, LPARAM l)
{
    NotepadInstance *inst =
        reinterpret_cast<NotepadInstance *>(GetWindowLongPtrW(h, GWLP_USERDATA));
    switch (m)
    {
    case WM_ERASEBKGND:
        return 1;
    case WM_PAINT:
    {
        PAINTSTRUCT ps;
        HDC hdc = BeginPaint(h, &ps);
        RECT rc;
        GetClientRect(h, &rc);
        if (!inst)
        {
            EndPaint(h, &ps);
            return 0;
        }
        FillRoundRect(hdc, rc, Dpi(inst, 8), inst->theme.BgCard);
        StrokeRoundRect(hdc, rc, Dpi(inst, 8), inst->theme.Border);
        if (!inst->menuItems)
