First, RefreshTheme. Also add a `RedrawWindow` helper:

```cpp
static void RefreshTheme(NotepadInstance *inst)
{
    ApplyThemeToDocuments(inst);

    // GDI brushes handed to WM_CTLCOLOR* carry the previous palette.
    if (inst->brSearchBg)
    {
        DeleteObject(inst->brSearchBg);
        inst->brSearchBg = nullptr;
    }
    if (inst->brAppBg)
    {
        DeleteObject(inst->brAppBg);
        inst->brAppBg = nullptr;
    }

    // RDW_ALLCHILDREN reaches the toolbar host, its owner-draw buttons, and the
    // search fields; invalidating only the panel leaves them painted with the
    // previous palette.
    if (inst->hSelf)
    {
        RedrawWindow(inst->hSelf, nullptr, nullptr,
                     RDW_INVALIDATE | RDW_ERASE | RDW_ALLCHILDREN | RDW_UPDATENOW);
    }
    if (inst->hToolbarHost)
    {
        RedrawWindow(inst->hToolbarHost, nullptr, nullptr,
